package agent

import (
	"context"
	"encoding/base64"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"reasonix/internal/event"
	"reasonix/internal/provider"
	"reasonix/internal/tool"
	"reasonix/internal/tool/builtin"
)

// e2eOnePixelPNG is a real 1x1 PNG so the generated bytes pass the same image
// validation an attached image does.
var e2eOnePixelPNG = func() []byte {
	raw, err := base64.StdEncoding.DecodeString("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR4nGP4z8DwHwAFAAH/iZk9HQAAAABJRU5ErkJggg==")
	if err != nil {
		panic(err)
	}
	return raw
}()

// TestGenerateImageEndToEndThroughAgentLoop drives the whole path a real turn
// takes: the model asks for generate_image, the workspace assembles that tool
// from an ImageGenSpec (the resolved [imagegen] endpoint, exactly like boot),
// the tool calls a real HTTP endpoint, saves the image inside the workspace,
// and the image rides the tool message's structured image channel. Only the
// model and the image endpoint are test doubles.
func TestGenerateImageEndToEndThroughAgentLoop(t *testing.T) {
	dir := t.TempDir()
	var requests int
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		requests++
		if r.Method != http.MethodPost || r.URL.Path != "/images/generations" {
			t.Errorf("request = %s %s", r.Method, r.URL.Path)
		}
		if got := r.Header.Get("Authorization"); got != "Bearer e2e-key" {
			t.Errorf("authorization = %q", got)
		}
		fmt.Fprintf(w, `{"data":[{"b64_json":%q}]}`, base64.StdEncoding.EncodeToString(e2eOnePixelPNG))
	}))
	defer srv.Close()

	ws := builtin.Workspace{
		Dir:        dir,
		WriteRoots: []string{dir},
		ImageGen:   builtin.ImageGenSpec{BaseURL: srv.URL, APIKey: "e2e-key", Model: "Tongyi-MAI/Z-Image-Turbo"},
	}
	reg := tool.NewRegistry()
	for _, tl := range ws.Tools("generate_image") {
		reg.Add(tl)
	}
	if _, ok := reg.Get("generate_image"); !ok {
		t.Fatal("generate_image was not assembled into the registry")
	}

	prov := &scriptedProvider{name: "p", turns: [][]provider.Chunk{
		{toolCallChunk("img-1", "generate_image", `{"prompt":"a red cube"}`), {Type: provider.ChunkDone}},
		{{Type: provider.ChunkText, Text: "done"}, {Type: provider.ChunkDone}},
	}}
	a := New(prov, reg, NewSession(""), Options{}, event.Discard)
	if err := a.Run(context.Background(), "draw a red cube"); err != nil {
		t.Fatalf("Run: %v", err)
	}

	var toolMsg *provider.Message
	for i := range a.sess.conversation.Messages {
		m := &a.sess.conversation.Messages[i]
		if m.Role == provider.RoleTool && m.Name == "generate_image" {
			toolMsg = m
			break
		}
	}
	if toolMsg == nil {
		t.Fatal("no generate_image tool message recorded")
	}
	if len(toolMsg.Images) != 1 || !strings.HasPrefix(toolMsg.Images[0], "data:image/png;base64,") {
		t.Fatalf("tool message images = %v", toolMsg.Images)
	}
	if !strings.Contains(toolMsg.Content, ".reasonix/generated/") {
		t.Fatalf("tool message content = %q", toolMsg.Content)
	}
	if requests != 1 {
		t.Fatalf("image endpoint requests = %d, want 1", requests)
	}
	generated := filepath.Join(dir, ".reasonix", "generated")
	entries, err := os.ReadDir(generated)
	if err != nil || len(entries) != 1 {
		t.Fatalf("generated files = %v (err %v)", entries, err)
	}
	saved, err := os.ReadFile(filepath.Join(generated, entries[0].Name()))
	if err != nil || string(saved) != string(e2eOnePixelPNG) {
		t.Fatalf("saved bytes differ: %v", err)
	}
}
